globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-28 07:34:55 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"「ロリポップ！レンタルサーバー」の平文パスワード情報などが漏えい。GMOペパボの内部システムに不正アクセス　顧客情報51万6564件が漏えいの可能性、対象者に個別メール連絡","url":"https://internet.watch.impress.co.jp/docs/news/2160136.html","source":"Hatena","published_at":"2026-11-27 21:29","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ロリポップ！レンタルサーバーで不正アクセス、平文パスワード含む情報漏洩","summary":"GMOペパボが運営する「ロリポップ！レンタルサーバー」等の内部システムが不正アクセスを受け、顧客情報51万6564件が漏洩した可能性があると発表されました。一部のパスワードが平文で保存されていたことが判明しています。\n\n同社は該当するパスワードを強制リセットし、対象者に個別連絡を行っています。平文保存という管理体制に対し、セキュリティの観点から大きな批判が集まっており、今後の再発防止策が問われています。","importance":10},{"title":"LLM に「材料にない数字」を言わせない：魚の質問欄を、指示ではなく答えの検査で守る","url":"https://zenn.dev/zennpay/articles/ab648c77094b5c","source":"Zenn","published_at":"2026-11-27 21:44","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"LLMの嘘を防ぐ：質問欄の答えを材料と照合して検査する仕組み","summary":"LLMを用いたアプリの質問欄において、モデルが「材料（DB情報）にない数字」を回答するリスクを回避する手法が解説されました。プロンプトによる指示だけでなく、出力された答えから数字を抜き出し、材料と照合する検査工程を設けています。\n\n検査に失敗した場合は別のプロバイダへ切り替えることで、回答の信頼性と可用性を両立させています。この仕組みにより、指示を守らないモデルでも安全に利用可能となり、コスト効率の良い運用が実現しました。","importance":9},{"title":"AI の加速を受け止める開発基盤の現在地とこれから","url":"https://zenn.dev/rehabforjapan/articles/ai-era-dev-foundation-progress-202612","source":"Zenn","published_at":"2026-11-27 10:27","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI時代の開発生産性を最大化する「開発基盤」の再定義と強化","summary":"AIエージェントによるコード生成が普及する中、真の生産性向上には「堅牢な開発基盤」が不可欠であると説く。DORAレポート等の知見を引用し、AIは既存の組織の強みと弱みを増幅させる「増幅器」であると指摘。土台が弱い状態でAIを導入しても、不安定さやレビュー負荷の増大を招くだけであると警鐘を鳴らしている。\n\n解決策として、小さなバッチでのリリース、CI/CDの高速化、E2Eテストの整備といった基本プラクティスの徹底を推奨。AIへの指示を増やすよりも、テストや静的解析でコードの正しさを担保できる環境を構築することが、長期的にはAIの恩恵を最大限に引き出す鍵になると結論付けている。","importance":9},{"title":"DNAで『マインクラフト』のように立体構造を構築する技術が登場、合計400個のDNAブロックでナノサイズの複雑な構造の形成に成功","url":"https://gigazine.net/news/20261127-dna-polycube-like-minecraft/","source":"Hatena","published_at":"2026-11-27 12:48","genre":"other","genre_label":"総合・その他IT","headline":"DNAブロックをマインクラフトのように組み上げるナノ構造形成技術","summary":"アリゾナ州立大学の研究チームが開発した、DNAブロックを自己組織化させて複雑な3次元ナノ構造を形成する「DNAポリキューブ」技術を紹介。DNAの塩基対の結合ルールを設計することで、溶液中で立方体ブロックが自発的に組み上がり、メンガーのスポンジのような複雑な形状を形成することに成功した。\n\nこの技術は、ナノロボットや3次元電子回路の製造への応用が期待されている。ブロックの種類を最小限に抑えるアルゴリズムにより製造コストも抑制可能であり、将来的に環境に応じて形状を変える分子レベルのデバイス開発への道を開くものとして注目される。","importance":7},{"title":"価格.comのAI駆動による全面刷新の現在地と振り返り","url":"https://speakerdeck.com/tkyowa/kakaku-com-ai-driven-system-renewal-202611","source":"Hatena","published_at":"2026-11-27 16:25","genre":"web","genre_label":"Web開発・言語","headline":"価格.comのAI駆動による大規模システム刷新「DODAIプロジェクト」の現在地","summary":"価格.comが約960万行のレガシーシステムをAIで刷新する「DODAIプロジェクト」の半年間の振り返り。ワークフロー型と自律エージェント型の比較や、人間がコードを読み書きする機会が減ったことによる技術選定の変化について議論した。\n\n大規模リプレイスにおけるAI活用の実践的な知見が共有されている。特に「ハーネスは薄くてよい」という考え方の検証や、AIの進化に合わせた開発構造の適応は、今後の大規模システム開発における重要なモデルケースとなる。","importance":8},{"title":"Claude Code で KiCad 基板を設計して JLCPCB に発注し、Codex とも同じ条件で比べた","url":"https://zenn.dev/kzchd/articles/ai-kicad-pihat-claude-codex","source":"Zenn","published_at":"2026-11-27 19:30","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Claude Codeを活用したKiCad基板設計と自動検査による発注プロセス","summary":"Raspberry Pi用I/O基板をClaude Codeを用いて設計し、JLCPCBへ発注した事例。AIの設計結果を鵜呑みにせず、ERC/DRCに加え、独自の検査スクリプト（ゲート）を設けることで、ピンの接続ミスなどを機械的に排除する仕組みを構築した。\n\nAI駆動開発において、AIの「できました」をそのまま信用せず、人間が定義した要件と突き合わせる「ゲート」を設ける手法は、基板設計のような物理的なミスが許されない領域で特に有効である。AIの能力を活かしつつ、人間が品質管理の要所を制御するハイブリッドな開発フローが示されている。","importance":7},{"title":"「ロリポップ！レンタルサーバー」および関連サービスに対する不正アクセスによるお客様情報の漏えいについて - ロリポップ！レンタルサーバー","url":"https://lolipop.jp/info/news/8279/","source":"Hatena","published_at":"2026-11-27 15:15","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ロリポップ！レンタルサーバーにおける不正アクセスによる情報漏えい","summary":"ロリポップ！レンタルサーバーおよび関連サービスにおいて、第三者による不正アクセスが発生し、約51万件の顧客情報が漏えいしたことを報告。データ分析基盤を経由した不正アクセスにより、氏名、郵便番号、メールアドレス、生年月日などが流出した。\n\n一部のユーザーについては、FTP・WebDAVのパスワードやBasic認証のID・パスワードも含まれており、該当するパスワードは無効化済み。クレジットカードや銀行口座情報の漏えいは確認されていない。現在は捜査機関と連携して調査を継続しており、再発防止策の策定とセキュリティ体制の強化を急いでいる。","importance":10},{"title":"はじめての Lean","url":"https://unaoya.github.io/lean-intro/","source":"Hatena","published_at":"2026-11-27 20:19","genre":"other","genre_label":"総合・その他IT","headline":"証明検査の仕組みを理解する「はじめてのLean」教材公開","summary":"Leanを用いた証明検査の仕組みを学ぶための教材が公開されました。コードを書くことよりも、証明が機械的に検証される論理構造を理解することに主眼を置いています。\n\n「命題は型であり、証明はその型の項である」という対応関係を軸に、依存関数型や帰納型を学びます。mathlibを使わず標準環境のみで構成されており、ブラックボックスを排除して数学的証明の検証プロセスを深く理解したいエンジニアや学生に最適な内容です。","importance":5},{"title":"業務向け「Copilot」アプリに「Office」を統合、人とエージェントが協働する「Workspaces」も【Ignite 2026】／「Home」は一般提供、自律型の「Autopilot」はFrontier向けに展開開始","url":"https://forest.watch.impress.co.jp/docs/news/2159782.html","source":"Hatena","published_at":"2026-11-27 16:28","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Microsoft Ignite 2026：Copilotの新機能と自律型エージェントの展開","summary":"Microsoft Ignite 2026にて、業務向けCopilotの新機能が発表された。CopilotアプリへのOffice統合や、人とエージェントが協働する「Workspaces」、自律型エージェント「Autopilot」などが含まれる。\n\nAIが単なるアシスタントから、自律的にタスクを遂行し、人間と協働するパートナーへと進化している。特に「Autopilot」や「Workspaces」の導入は、業務プロセスそのものをAI中心に再構築する動きを加速させるだろう。","importance":9},{"title":"【資料公開】コードを書くAI、アーキテクチャーを決める組織","url":"https://www.ryuzee.com/contents/blog/14629","source":"Hatena","published_at":"2026-11-27 20:42","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI時代のアーキテクチャ：チームの境界が組織とプロダクトを決める","summary":"AIによるコーディングが普及する中、アーキテクチャの決定権は依然として人間と組織にあるという視点から、チームの境界設計の重要性を説いた登壇資料です。AIは境界の引き方を増幅させ、プロダクトの進化を加速させます。\n\n境界の変更を日常的に行える組織構造の構築や、ビルドが落ちる仕組みによる境界の強制が重要です。AIを活かすも殺すも組織の境界次第であり、技術基盤と組織再編をセットで整備することが、少人数で大きな成果を出す鍵となります。","importance":8},{"title":"Kong×MuleSoft の外部連携を12項目で固め、再検証で落とし穴を3つ見つけた話","url":"https://zenn.dev/kensudo1203/articles/edbd45f1bf44d1","source":"Zenn","published_at":"2026-11-27 11:06","genre":"web","genre_label":"Web開発・言語","headline":"Kong×MuleSoft連携におけるセキュリティ強化と再検証の落とし穴","summary":"APIゲートウェイKongと連携基盤MuleSoftを用いた銀行システムサンプルにおいて、外部連携機能をセキュアに実装するための12項目の対策と、その後の再検証で見つかった落とし穴を記録した記事。APIキー認証からOAuth 2.0への移行、署名付き行員トークンの導入、mTLSによる通信制限、ネットワーク分離など、多層的な防御策を講じた。\n\nしかし、再検証ではテストコードの不備や設計の漏れが発覚。セキュリティ実装においては、ドキュメントやテストが通っている状態を鵜呑みにせず、徹底的な再確認と防御の多重化が不可欠であることを示している。","importance":8},{"title":"2026年に刊行されてよかったなと思うコンピューター技術書 - golden-luckyの日記","url":"https://golden-lucky.hatenablog.com/entry/2026/11/27/111643","source":"Hatena","published_at":"2026-11-27 11:26","genre":"other","genre_label":"総合・その他IT","headline":"2026年に出版された骨太なコンピューター技術書の選書リスト","summary":"AIによる開発加速で技術書の需要が変化する中、2026年に出版された書籍の中から、著者の視点や出版の意義を感じさせる「骨太な技術書」を厳選して紹介した記事。Webセキュリティ、バイナリ解析、ブラウザエンジニアリング、OS自作、検索システム、OpenTelemetryなど、AI関連以外の専門的な技術書が多数出版されていることを強調している。\n\n技術の深淵に触れる書籍を手に取ることは、エンジニアとしての成長や著者への応援につながるとして、読者に書籍購入やITエンジニア本大賞への投票を呼びかけている。","importance":5},{"title":"再現性のあるAI開発環境構築 #1 ―― Ghostty と Herdr で、Claude Code を並べる作業場を組む","url":"https://zenn.dev/circularuins/articles/reproducible-ai-env-base-terminal","source":"Zenn","published_at":"2026-11-27 10:39","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"GhosttyとHerdrで構築するClaude Code並行作業環境の再現手順","summary":"Claude Codeのセッションを複数並べて効率的に開発を行うための、ターミナル環境構築ガイド。ターミナルエミュレータ「Ghostty」と、ペイン管理ツール「Herdr」を組み合わせ、AI開発に最適化された作業場を再現可能な形で設定する手順を公開している。\n\n設定にはHomebrewを使用し、Ghosttyの透過背景やNerd Fontの活用、Herdrによるセッション管理とステータスライン表示までを網羅。さらに、Claude CodeとHerdrを連携させ、セッションの状態をサイドバーで可視化するフックの設定方法も解説しており、AIエージェントを活用した並行作業の生産性を高めるための具体的な構成案となっている。","importance":7},{"title":"「勇気ありすぎだろ」GMOが買収した激安サーバー「ロリポップ！」が顧客情報の漏洩を公表、漏れた一部パスワードを“平文で”保存していた模様","url":"https://togetter.com/li/2775731","source":"Hatena","published_at":"2026-11-27 20:42","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ロリポップ！のパスワード平文保存問題にSNSで批判殺到","summary":"ロリポップ！レンタルサーバーの顧客情報漏洩ニュースにおいて、一部のパスワードが平文で保存されていた事実が判明し、SNS上で大きな議論を呼んでいます。サーバー運営企業としての技術力やセキュリティ意識の低さが厳しく指摘されています。\n\nBasic認証やFTPパスワードの流出リスクに加え、他サービスへの使い回しによる二次被害への懸念も広がっており、業界全体でパスワード管理のあり方が改めて問われる事態となっています。","importance":9},{"title":"さくさく作れる毎日を支える、AI 時代の開発環境 — 隔離・コンテキスト・ガードレール・検証の整理 - [はてなCMS] 電通総研 テックブログ","url":"https://tech.dentsusoken.com/entry/2026/11/27/133501","source":"Hatena","published_at":"2026-11-27 14:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI時代の開発環境を支える隔離・コンテキスト・検証の4本柱","summary":"コーディングエージェントを前提とした開発環境において、人間が手動で行っていた開発プロセスをどのように自動化・最適化すべきかを論じた実践記事。開発環境を「隔離基盤」「コンテキスト設計」「決定論的ガードレール」「多層検証」の4つの柱で整理している。\n\n具体的には、microVMによる隔離、worktree単位の環境分離、Gitフックによる即時フィードバック、プロパティベーステストや異種モデルによる敵対的検証などを紹介。AIの生成速度に人間が追いつくための「舗装」として、これらの基本技術を組み合わせ、自動化と人間による判断の境界を明確にすることが重要であると結論づけている。","importance":9},{"title":"◯✗ゲーム++：FIFO ◯✗ゲームにおいて先手が 13 手で勝つことの証明","url":"https://zenn.dev/akitenkrad/articles/wq6lzq7xa036ff","source":"Zenn","published_at":"2026-11-27 08:00","genre":"other","genre_label":"総合・その他IT","headline":"FIFO ◯✗ゲームにおける先手の13手必勝の数学的証明","summary":"古い手が消えるルールを持つ「FIFO ◯✗ゲーム（T3・k=3）」において、先手が13手で勝利することを全数探索に頼らずに証明した技術記事。古典的な◯✗ゲームとは異なり、二重リーチではなく「相手の最も古い手が自分の完成マスにある」というトラップで勝敗が決まる特性を持つ。\n\n証明は、先手が13手目までに勝てることと、13手未満では勝てないことの2点を、6つの補題を組み合わせて上下から挟み込む手法で実施。ゲームの局面をランク付けし、最善手を選択し続けた場合の決着までの手数を理論的に導き出すことで、なぜ13手で決着するのかという問いに対して数学的な裏付けを与えている。","importance":5},{"title":"AIのレバレッジはカスタマーフロントから設計する","url":"https://zenn.dev/knowledge_graph/articles/ai-leverage-customer-front","source":"Zenn","published_at":"2026-11-27 18:48","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AIのレバレッジを最大化するカスタマーフロント業務の設計戦略","summary":"AI導入による業務効率化を事業成果に結びつけるには、単なる作業の自動化ではなく、カスタマーフロント（営業・サポート等）の判断と行動を設計することが不可欠である。AIは組織の仕事の進め方を増幅するため、曖昧な業務をAIに任せると負のレバレッジがかかるリスクがある。\n\n結論として、AIに任せる範囲を「回答作成」から「約束の記録・担当者への連携・対応の抜け漏れ防止」まで広げ、顧客体験を向上させる設計が重要である。また、コモディティ化するAI技術の上で差別化を図るには、自社のドメイン知識と顧客データをAIが扱える形に整えることが鍵となる。","importance":8},{"title":"静的サイト251ページのAI検索対応：facts.json・llms-full.txt・.md配信の実装記録","url":"https://zenn.dev/kurodaschool/articles/e478038976268c","source":"Zenn","published_at":"2026-11-28 00:17","genre":"web","genre_label":"Web開発・言語","headline":"静的サイトをAI検索に最適化する5つの実装手法","summary":"静的サイトをChatGPT検索やClaudeなどのAI検索エンジンに引用されやすくするための実装記録です。フレームワークを使わず、Pythonスクリプトでfacts.jsonやllms-full.txtを生成する構成を採用しました。\n\n主な手法として、一次情報の構造化、Markdown形式での本文配信、構造化データへのSpeakable追加、IndexNowによる更新通知を導入しています。AI向けのファイルと人間向けのページが乖離しないよう、ビルド時に整合性をチェックする仕組みも重要です。","importance":7},{"title":"drift のマイグレーション戦略","url":"https://zenn.dev/narun/articles/20261127-drift-migration-strategy","source":"Zenn","published_at":"2026-11-27 20:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Flutterアプリにおけるdriftデータベースの堅牢なマイグレーション戦略","summary":"FlutterアプリのローカルDB（drift）において、複雑化しがちなマイグレーションを安全に行うための戦略がまとめられました。ステップごとの移行、トランザクションの活用、テストの導入を方針としています。\n\n従来の条件分岐による管理から、スキーマバージョンを1つずつ上げるステップ方式へ移行することで、失敗時のリスクを低減します。実際のTODOアプリを題材に、データ移行のテスト手法やエラーハンドリングまで網羅的に解説されています。","importance":6},{"title":"Kizuna AI、春猿火ら9組がバーチャル空間に集結　VRChat音楽フェス「ESPERA」レポート","url":"https://kai-you.net/article/97275","source":"Hatena","published_at":"2026-11-27 18:21","genre":"other","genre_label":"総合・その他IT","headline":"VRChat音楽フェス「ESPERA」開催、バーチャル空間の音楽体験","summary":"VRChatで開催された音楽フェス「ESPERA -AdHoc Live Festival 2026-」のレポート。RIOT MUSICとカルチュア・エンタテインメントが共同企画し、Kizuna AIや春猿火らが出演した。\n\nバーチャル空間における音楽イベントは、物理的な制約を超えた演出が可能であり、エンターテインメントの新たな形として定着しつつある。サンリオVfesなどと同様、企業がVRChatに注力する背景には、バーチャル空間が新たな文化圏として確立されている現状がある。","importance":4},{"title":"Linuxカーネルのバグ「TCPanic」を発見、TCP通信のみでホストが停止する脆弱性 | Ikotas Labs","url":"https://ikotaslabs.com/news/2026-11-27","source":"Hatena","published_at":"2026-11-27 18:14","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"LinuxカーネルのTCP処理に起因する脆弱性「TCPanic」が発見される","summary":"Ikotas Labsが、LinuxカーネルのTCP処理における脆弱性「TCPanic（CVE-2026-99288）」を発見した。外部からのTCP通信のみでホスト全体が停止する可能性がある深刻なバグであり、Linux 7.3.4で修正された。\n\nマルチコア環境において、接続情報の検索と解放が競合することで発生する。インターネット経由の攻撃も可能な現実的な脅威であり、ロードバランサー等の構成に関わらず、未修正のLinuxホストが直接影響を受けるため、早急なアップデートが推奨される。","importance":9},{"title":"AIエージェントにWebのファイルを取得させるリスクについて考える","url":"https://zenn.dev/layerx/articles/65b4828efcaee2","source":"Zenn","published_at":"2026-11-27 10:48","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントに外部ファイル読み取り権限を与える際のリスクと対策","summary":"AIエージェントにWeb上のファイルを読み取らせる機能は、利便性が高い反面、セキュリティ上の重大なリスクを孕んでいる。特に「非公開データへのアクセス」「信頼できないコンテンツの読み込み」「外部通信」が組み合わさることで、間接プロンプトインジェクションによる情報漏えいやエージェントの乗っ取りが可能になる「致命的な3点セット」について警告している。\n\n対策として、モデルの改良だけに頼るのではなく、アプリ側で「外部資料」と「内部データ」の出所を明確に区別することや、ツール実行時に制約を設けて被害を最小限に抑える構成の重要性を強調。実際に架空のPDFに隠し指示を埋め込む実験を通じ、人間には見えない指示がAIの挙動を操作できてしまう危険性を実証している。","importance":9},{"title":"顧客情報を守るため、売上15％の自社ECを閉店　ドールメーカーが明かした「決断」の背景","url":"https://www.itmedia.co.jp/news/article/2611/27/2000003518/","source":"Hatena","published_at":"2026-11-27 17:09","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"アゾンインターナショナル、個人情報保護を優先し自社ECを閉店","summary":"ドールメーカーのアゾンインターナショナルが、AIによるサイバー攻撃の高度化と情報漏えいリスクを鑑み、売上の約15％を占める自社ECサイト「AZONET」を閉店した。個人情報を「持たない」方針への転換を決定した。\n\n暗号化してもAIによる復号リスクやランサムウェア被害を完全に防ぐことは困難であるという判断に基づく。顧客データを失う不利益よりも、顧客の個人情報保護を最優先する経営判断であり、セキュリティリスクに対する企業の姿勢として注目される。","importance":8},{"title":"[JSC] 数値で構成される配列に対して Array.prototype.flat を最適化した","url":"https://zenn.dev/itsu_dev/articles/1942c82c2f2e27","source":"Zenn","published_at":"2026-11-27 20:52","genre":"web","genre_label":"Web開発・言語","headline":"JavaScriptCoreにおける数値配列のflatメソッド最適化","summary":"WebKit/JavaScriptCoreのArray.prototype.flat実装において、数値配列に対する処理を最適化し、高速化を実現したパッチの解説です。従来のアルゴリズムは汎用的ですが、数値のみで構成される配列では冗長な処理が含まれていました。\n\nECMAScript仕様に基づき、配列の疎密性やネストの有無を考慮することで、コピー処理を効率化しています。特定のユースケースにおいてパフォーマンス向上が期待できる技術的な改善事例です。","importance":7},{"title":"簡単な回路だと油断したら、ハマり続けた話　～ｽﾀｯｸﾁｬﾝおでかけバージョン試作記～","url":"https://zenn.dev/mar_a/articles/3270cb5753ac25","source":"Zenn","published_at":"2026-11-27 21:21","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"ｽﾀｯｸﾁｬﾝおでかけ版の試作でハマった回路設計とコネクタの罠","summary":"キャタピラ付き「ｽﾀｯｸﾁｬﾝ」の開発過程で直面した、回路設計とコネクタのトラブル記録です。電源ノイズ対策として昇圧コンバータでサーボ用電源を分離したものの、コネクタのピン配置の反転やPWM設定のミスにより、動作不良に苦戦しました。\n\nテスターのみを用いた切り分け作業を通じて、設計ミスや設定の不備を一つずつ解消していく過程が詳細に綴られています。ハードウェア開発における「思い込み」の危険性と、検証の重要性を再確認する内容です。","importance":5},{"title":"止まらないKARTE漏えい　契約終了後「削除されたはず」のデータ流出相次ぐ　「人的オペレーションと管理の不備」","url":"https://www.itmedia.co.jp/news/article/2611/27/2000003517/","source":"Hatena","published_at":"2026-11-27 15:13","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"KARTE不正アクセス問題、契約終了後のデータ削除不備が露呈","summary":"プレイドの「KARTE」への不正アクセス問題で、契約終了後も削除されるべき顧客データが残存し、流出した事例が相次いでいる。人的オペレーションと管理の不備が原因とされ、複数の企業がデータの完全消去を求めている。\n\nSaaS利用におけるデータガバナンスの重要性が浮き彫りになった。契約終了後のデータ削除プロセスが適切に運用されていないことは、セキュリティリスクを増大させる。企業は委託先のデータ管理体制を厳格に監視する必要がある。","importance":9},{"title":"LT のライブ字幕を、登壇前のスライドで技術用語に強くする（AmiVoice API）","url":"https://zenn.dev/ponyo877/articles/117c1fc0728161","source":"Zenn","published_at":"2026-11-27 23:46","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"登壇資料から技術用語を抽出し、ライブ字幕の精度を向上させる手法","summary":"勉強会やLTでのライブ字幕において、汎用音声認識では崩れやすい技術用語を正確に表示するための手法が紹介されました。登壇前のスライドPDFからClaudeを用いて用語と読みを抽出し、AmiVoice APIの単語登録に活用します。\n\nシステムはCloudflare Workers上で動作し、リアルタイム字幕配信と登壇後の振り返り分析を統合しています。辞書登録の自動化により、登壇者の手間を抑えつつ、専門用語の認識精度を大幅に高めることが可能です。","importance":8},{"title":"【重要】R-18設定のクリエイターへの支援におけるPayPal決済のお取り扱い終了について｜pixivFANBOX公式｜pixivFANBOX","url":"https://official.fanbox.cc/posts/12998412","source":"Hatena","published_at":"2026-11-27 20:42","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"pixivFANBOX、R-18クリエイターへの支援でPayPal決済を終了","summary":"pixivFANBOXは、R-18設定のクリエイターに対する支援金支払い方法において、PayPal決済の取り扱いを終了すると発表しました。これは以前告知されたMastercardの一部取り扱い終了に伴う続報となります。\n\n決済手段の変更はクリエイターの収益に直結するため、対象となるユーザーは早急な支払い方法の確認と変更が求められます。","importance":6},{"title":"シンプルな構文で美しい図を自動生成する「D2」が進化、非営利化で独自レイアウトエンジンもオープンソース化","url":"https://gigazine.net/news/20261127-d2/","source":"Hatena","published_at":"2026-11-27 23:05","genre":"web","genre_label":"Web開発・言語","headline":"図解生成ツール「D2」が非営利化し、独自レイアウトエンジンを公開","summary":"テキストから図形や矢印を自動生成するツール「D2」が、運営体制を非営利に移行し、独自の自動配置エンジン「TALA」をオープンソース化しました。v0.9.0では描画処理が大幅に高速化されています。\n\nD2は手描き風モードやアニメーション、ASCII出力など多彩な表現に対応しており、構成図の作成に最適です。複数のレイアウトエンジンを使い分けることで、複雑なシステム構成図からプレゼン資料まで、同一のテキストから柔軟に生成可能です。","importance":6},{"title":"XYZA、何度も自由に描き替え可能なカラーE Ink搭載スマートキーホルダー","url":"https://www.itmedia.co.jp/pcuser/articles/2611/27/news083.html","source":"Hatena","published_at":"2026-11-27 18:23","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"XYZA、充電不要でNFC書き換え可能なカラーE Inkキーホルダーを発売","summary":"XYZAが、バッテリー非搭載で充電不要の1.54型カラーE Inkパネル内蔵スマートキーホルダーを発表した。NFC対応スマートフォンをかざすことで、書き換え時の微弱な電波を利用して表示内容を更新できる。\n\nバッテリーレスで半永久的に表示を維持できる点は、ウェアラブルデバイスやアクセサリとしての利便性が高い。技術的にはNFCの給電機能を活用したユニークな実装であり、電子ペーパー技術の応用範囲の広さを示す事例である。","importance":5},{"title":"大阪大学、学生と教職員のメアド5万件漏洩　アララへの不正アクセス - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUF272NY0X21C26A1000000/","source":"Hatena","published_at":"2026-11-28 02:19","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"大阪大学、安否確認システムへの不正アクセスによりメアド5万件が漏洩","summary":"大阪大学は、災害時の安否確認システム「ANPIC」のメール配信委託先であるアララ社が不正アクセスを受けた影響で、学生・教職員のメールアドレス5万1891件が漏洩したと発表しました。氏名や所属などの個人情報は含まれていません。\n\n大学側は対象者に対し、不審なメールへの警戒を呼びかけています。現在、当該システムの利用を停止しており、安全性が確認されるまでは代替手段で運用を行う方針です。","importance":7},{"title":"AI時代にテスト設計を学び直す #3 頼み方を工夫したら、AIは観点をどこまで拾えるようになるか","url":"https://zenn.dev/a_maru/articles/1005a2c3f41c39","source":"Zenn","published_at":"2026-11-27 14:15","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIへのテスト設計指示を工夫し、観点網羅性を高める実験と考察","summary":"AIにテスト設計を依頼する際、プロンプトの指示内容を工夫することで、AIが拾えるテスト観点がどう変化するかを検証した記事。ISTQBのCT-GenAIの型に基づき、役割やコンテキストを詳細に定義したプロンプトを試行した結果、AIは指定した技法に基づいた表形式の報告や境界値の確認など、指示に忠実な動きを見せた。\n\n一方で、AIの「欲」による過剰な挙動や、仕様の食い違いに対する判断の難しさも浮き彫りになった。結論として、AIにテストを任せる際は、単に指示を出すだけでなく、承認プロセスや確認の決まり（ハーネス）を整備し、人間が「何を見るべきか」を定義し続けることが不可欠であると説いている。","importance":8},{"title":"Dress Codeに入社して1か月、AIに実装を任せて気づいた、自分に足りないもの","url":"https://zenn.dev/dress_code/articles/578058ec645505","source":"Zenn","published_at":"2026-11-27 13:00","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI実装時代にプロダクトエンジニアが直面する知識不足と学びのループ","summary":"AIに実装を任せる開発体制において、エンジニアが直面する「ドメイン知識」や「プロダクト固有知識」の不足について、入社1ヶ月の経験を基に綴ったエッセイ。実装をClaude Codeに任せ、その間に知識をインプットし、上がってきた成果物を承認するというループを回す中で、設計原則や業務ルールを見落とす課題に直面した。\n\nAIを使いこなすには、単にコードを書く能力だけでなく、承認者として「何を見るべきか」という観点を持ち、見落としをハーネス（手順や確認の決まり）に反映し続けるマネジメント的な視点が不可欠であると述べている。","importance":6},{"title":"Agentic CX Designer のアプリケーションを SDK でコード管理してみた","url":"https://zenn.dev/aws_japan/articles/92ccd59867575d","source":"Zenn","published_at":"2026-11-27 17:48","genre":"web","genre_label":"Web開発・言語","headline":"Amazon ConnectのAgentic CX DesignerをSDKでコード管理する手法","summary":"Amazon ConnectのAgentic CX Designer（ACXD）において、GUIでの構築だけでなく、SDKを用いてフローをコード管理（IaC）する手法を解説。Node.jsスクリプトを用いてアプリケーションのデプロイや管理を行うことで、変更履歴の追跡や自動化が可能になる。\n\nAIエージェントの構築をプログラマティックに行うことで、本番環境への展開やテストの再現性が向上する。SDKを活用した開発フローは、AIエージェントの運用を安定させ、大規模なカスタマーエクスペリエンス設計を支える重要な技術となる。","importance":6},{"title":"初期iPhoneは「携帯電話としてあり得ない」と思った　ガングロギャルが教えてくれた“技術普及の絶対条件”","url":"https://www.itmedia.co.jp/mobile/articles/2611/27/news079.html","source":"Hatena","published_at":"2026-11-27 15:42","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"モバイルインターネット普及の歴史から学ぶ「使いやすさ」の絶対条件","summary":"初期iPhoneの登場やiモードの普及を振り返り、技術が社会インフラとして普及するための条件を考察。ガングロギャルがiモードを積極的に利用した事例から、ITに縁遠い層にも恩恵を届けるための「使いやすさ」と「アクセシビリティ」の重要性を説く。\n\n技術的に優れているだけでは普及せず、ユーザーが日常的に利用するためのハードルをいかに下げるかが鍵となる。AIの台頭によりモバイルが生活不可欠なインフラとなった現在においても、この視点は変わらず重要である。","importance":5},{"title":"Leanで安全制約を書くと、ハザード候補がビルドエラーとして見つかる","url":"https://zenn.dev/kokeshim0chi/articles/lean-safety-constraint-build-error","source":"Zenn","published_at":"2026-11-27 13:40","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Leanを用いた安全制約の形式化によるハザード自動検出手法","summary":"システム安全工学のSTAMP/STPAの考え方を、定理証明支援系「Lean」を用いて形式化し、バッチ処理のハザードをビルドエラーとして検出する手法を提案した記事。一般的なテストでは網羅できない実行順序や入力の組み合わせによる事故を、安全制約を定理として記述することで、Leanがすべてのケースを検証し、満たさない箇所をビルドエラーとして指摘する。\n\nこれにより、ハザード候補を自動的に抽出可能となる。実装とモデルの乖離という課題はあるものの、コアロジックの安全性検証において、LLM生成コードの検証などへの応用が期待される。","importance":8},{"title":"禁止しても止まらないClaudeの「欲」を飼いならしてみる","url":"https://zenn.dev/rescuenow/articles/9d1e89a941f4f1","source":"Zenn","published_at":"2026-11-27 11:47","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claudeの過剰な「欲」を制御し、指示通りの実装をさせる実験","summary":"AIが頼まれていない挙動を勝手に追加する「欲」を、プロンプトの工夫で制御できるか検証した実験記録。禁止や肯定形での指示（ドキュメント化、Issue化）は効果が薄かったが、頼まれていない挙動を「xfail（失敗予定）」のテストとして書かせる指示を与えたところ、本体のコードには頼んだことだけが実装されるようになった。\n\nAIの過剰な挙動は「正しく動かしたい」という意図から生じていると推察し、その欲をテストという形で吐き出させることで、コードの品質と指示の遵守を両立させる手法を提案している。","importance":8},{"title":"サブスクの「お試し→自動更新」は客を逃していた？　新規購読者数は「お試し→自動解約」比23％減　140万人で実験","url":"https://www.itmedia.co.jp/news/article/2611/27/2000003503/","source":"Hatena","published_at":"2026-11-27 12:22","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"サブスクの「自動更新」は長期的な顧客獲得に悪影響を及ぼす可能性","summary":"サブスクリプションのお試し契約において、「自動更新」と「自動解約」の条件が顧客行動に与える影響を約140万人規模で検証した研究論文の解説。結果として、自動更新プランは短期的には収益を上げる可能性があるものの、解約忘れを懸念する消費者の心理的障壁となり、長期的な購読者数は自動解約プランの方が23％多かった。\n\nまた、不本意な契約は企業への不信感を生み、将来の優良顧客を遠ざけるリスクがある。この研究は、顧客の信頼を損なわない透明性の高いサブスクリプション設計の重要性を示唆している。","importance":6},{"title":"後回しできる設計、 前倒しすべき設計。","url":"https://speakerdeck.com/anizozina/akitekucha-kanfarensu-2026-atomawashi-dekiru-sekkei-maedaoshi-subeki-sekkei","source":"Hatena","published_at":"2026-11-27 16:20","genre":"web","genre_label":"Web開発・言語","headline":"コンパウンドプロダクトを支えるCoreDBとEvent Sourcingの設計思想","summary":"Dress Code株式会社による、コンパウンドプロダクト（複数のSaaSを統合するプラットフォーム）を支えるアーキテクチャの設計思想。CoreDBとEvent Sourcingを採用し、後回しにできる設計と前倒しすべき設計を明確に分けている。\n\nSaaS乱立による業務のサイロ化という社会課題に対し、データ基盤を統合するアプローチ。Event Sourcingを用いることで、データの変更履歴を保持し、将来的な拡張性や監査性を確保する設計は、複雑な業務ドメインを扱うプロダクト開発において参考になる。","importance":6},{"title":"GitHub ActionsからPATもGitHub App Private Keyも駆逐する","url":"https://zenn.dev/tmknom/articles/github-app-token-exchange-system","source":"Zenn","published_at":"2026-11-27 11:51","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"GitHub Actionsから長命なクレデンシャルを排除するGATESの紹介","summary":"GitHub ActionsにおけるPATやGitHub App Private Keyの管理リスクを解消するため、AWS LambdaとKMSを活用した「GATES (GitHub App Token Exchange System)」を開発した事例。GATESはGitHub OIDCとAWS KMSを組み合わせることで、Private Keyをワークフローに渡さずに一時的なGitHub App Tokenを払い出す「キーレス」な認証を実現する。\n\nこれにより、長命なクレデンシャルが漏洩するリスクを排除し、運用負荷を大幅に軽減できる。KMSの署名機能を活用し、Lambdaすら鍵の平文を参照しない設計が特徴である。","importance":8},{"title":"BigQuery でレビュー分析：AI.CLASSIFY で感情、AI.GENERATE でキーワード配列を SQL だけで取り出す","url":"https://zenn.dev/google_cloud_jp/articles/9324b0f5425866","source":"Zenn","published_at":"2026-11-27 13:40","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"BigQueryのAI関数でレビュー分析をSQLのみで完結させる方法","summary":"BigQueryのAI関数（AI.CLASSIFY, AI.SCORE, AI.GENERATE）を活用し、外部サービスや複雑なパイプラインを構築せずに、SQLのみでレビューの感情分析やキーワード抽出を行う手法を解説。接続設定なしでVertex AIのGeminiを呼び出せるため、手軽に導入可能である。\n\n感情分析にはAI.CLASSIFY、満足度の数値化にはAI.SCORE、キーワード抽出にはAI.GENERATEのoutput_schema指定が有効である。また、複数の分析を1回のクエリで実行することでトークン消費を抑えるテクニックも紹介されており、データ分析業務の効率化に直結する内容となっている。","importance":7},{"title":"「制約の中で動かす」から「思想を持って育てる」へ。パッケージベンダー出身の社内SEがセーフィーで直面している日々","url":"https://zenn.dev/safie_inc/articles/9f0d9a522ad1ed","source":"Zenn","published_at":"2026-11-27 10:11","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"パッケージベンダー出身者が語る自社システム開発における「思想」の重要性","summary":"パッケージベンダーからセーフィーへ転職した社内SEが、自社システム開発の現場で直面した課題と変化を綴る。前職ではパッケージの制約下での運用が主であったが、自社システムでは「システムの思想」を問われ、要望をそのまま実装するのではなく、将来的な整合性や運用負荷を考慮した設計が求められる点に苦労とやりがいを感じている。\n\n特に、営業・開発・QAなど多くの関係者が関わる環境下で、潜在的なニーズを汲み取り「開発できる形」に落とし込むプロセスの重要性を強調。ハードウェアとソフトウェアが複雑に絡み合う自社サービスにおいて、場当たり的な機能追加を避け、システム全体をどう育てていくかという視点を持つことの難しさと重要性を説いている。","importance":6},{"title":"既存のExcelを自動で編集したい──AIに書かせたOffice ScriptsとCopilot Studioで試してみた","url":"https://zenn.dev/upgradetech/articles/1bed37bcbf0732","source":"Zenn","published_at":"2026-11-26 12:37","genre":"web","genre_label":"Web開発・言語","headline":"Office ScriptsとCopilot StudioでExcelの形を変えずに自動化する","summary":"テーブル形式ではない複雑なExcelファイルを、作り変えることなくCopilot Studioのエージェントから操作する手法を検証。Office Scripts（TypeScript）を活用し、見出しの文字からセル位置を動的に特定することで、区切り行や小計行を含む台帳の検索・更新を実現した。\n\nAgent Builderで作成した「スクリプト生成エージェント」にプロンプトを工夫して指示することで、専門的なコードを書かずに自動化スクリプトを生成するプロセスを解説。エラー時の修正フローや、ファイルごとの設定を分離する設計など、実務で役立つ自動化のノウハウがまとめられている。","importance":7},{"title":"ISUCON2026 マルチリージョン構成におけるデータのインメモリ化 #isucon_namalog","url":"https://speakerdeck.com/kawasy/isucon2026-statemachine-replication-for-multi-region-in-memory-data-store-maruchi-rijon-kousei-niokeru-deta-no-in-memorika-e46becf2-a792-4df7-b614-7d36bae5e42e","source":"Hatena","published_at":"2026-11-27 10:52","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ISUCON2026優勝者が解説するマルチリージョンでのデータインメモリ化手法","summary":"ISUCON2026で優勝したAIエージェントが採用した、マルチリージョン構成におけるデータインメモリ化の設計と実装について解説。分散システムにおいて複数ノードの状態を一致させる「ステートマシン・レプリケーション（SMR）」の概念を軸に、書き込みの順序を保証しつつ、各リージョンで高速な読み取りを実現するためのアーキテクチャを詳述している。\n\n具体的には、中央のノードで書き込み順序を確定させ、各レプリカが同じ順序で更新を適用する手法を採用。決定性や全順序ブロードキャストの重要性を説き、実際の競技環境でどのように整合性を保ちながらパフォーマンスを最大化したか、その技術的背景と実装のポイントがまとめられている。","importance":8},{"title":"日本語のFull-duplex音声対話モデルを実際に動かしてみた話","url":"https://zenn.dev/knowledgework/articles/12a80d8cd4b21f","source":"Zenn","published_at":"2026-11-27 11:27","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"日本語Full-duplex音声対話モデル「J-Moshi-ext」の検証","summary":"人間同士のような自然な割り込みや相槌を可能にする「Full-duplex（全二重）音声対話」技術の動向と、日本語モデル「J-Moshi-ext」のローカル実行検証レポート。Moshiは音声認識・言語モデル・音声合成を統合的に扱うモデルであり、本記事ではApple Silicon搭載Macで動作可能なMLX版を用いて、その挙動を確認した。\n\nローカル環境で推論を実行することで、外部サービスに依存しない音声対話システムの構築可能性を探っている。音声対話技術の進化と、それを手元で再現・調査するエンジニアリングの重要性が示されている。","importance":7},{"title":"ドコモに聞く「新ahamo」の狙い　3段階制と165円値上げ、既存契約者に“40GBリミッター”実装の理由","url":"https://www.itmedia.co.jp/mobile/articles/2611/26/news074.html","source":"Hatena","published_at":"2026-11-26 16:33","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"ドコモahamo改定の狙い：段階制導入と容量増量による離脱防止","summary":"ドコモが12月1日に実施するahamoの料金改定について、その設計意図を解説。従来の30GBから40GBへの増量と、60GB・120GBまでの段階制導入の背景には、データ制限直前で利用を控えるユーザーの離脱を防ぐ狙いがある。\n\n値上げ幅を165円に抑えつつ、中容量帯のニーズに応えることで競争力を維持し、無制限プランへの誘導を図る戦略を説明。アンケートや利用データの分析に基づき、ユーザーの満足度と収支バランスを考慮した結果としての段階制であり、シンプルさを維持しつつ利便性を向上させるための工夫が凝らされている。","importance":6},{"title":"思いのままに変換したい〜日本語入力のためのVimプラグインCaskkを作った","url":"https://zenn.dev/ni57721/articles/vim-caskk-ime","source":"Zenn","published_at":"2026-11-27 20:00","genre":"web","genre_label":"Web開発・言語","headline":"Vimで快適な日本語入力を実現するSKKプラグイン「Caskk」","summary":"Vim向けの新しいSKKプラグイン「Caskk」が開発されました。画面を見ずに思い通りに変換できることを目指し、候補のピン留めや動詞・形容詞の語幹変換など、高度なカスタマイズ機能を備えています。\n\nAZIKユーザーにも配慮した設定方法や、非同期での辞書読み込みによる操作性の維持が特徴です。活用タグ付きの辞書も提供されており、Vim環境での日本語入力効率を大幅に向上させたいユーザーにとって強力なツールとなります。","importance":5},{"title":"iostatは正常なのにp99だけ遅い原因はcgroupのIOPS上限","url":"https://zenn.dev/shinagawa_web/articles/io-max-hidden-from-iostat","source":"Zenn","published_at":"2026-11-27 08:01","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"iostatで異常なしでもp99が遅延する原因はcgroupのIOPS上限","summary":"アプリケーションのp99レイテンシが跳ね上がる一方で、iostatの平均待ち時間やディスク使用率には異常が見られないという現象の原因を解説。これはcgroupのIOPS上限設定が引き起こす「blk-throttle」による待機が原因である可能性が高い。\n\nカーネルはIOPS上限を100ms単位の「スライス」で管理しており、スライス内で上限に達すると、残りの期間のI/Oは強制的に停止される。この停止時間はiostatのr_awaitには含まれないため、観測上は正常に見える。記事では、この仕組みがなぜ特定のパーセンタイルにのみ影響を与えるのかを論理的に解明し、fioを用いた検証結果を通じて、同時実行数と上限設定の関係を明らかにしている。","importance":8},{"title":"自動運転の予測軌跡の可視化動画を誰でも高速に作れるようにする","url":"https://zenn.dev/turing_motors/articles/cbf9872ca90166","source":"Zenn","published_at":"2026-11-26 17:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"自動運転の予測軌跡可視化動画を高速生成するAWS基盤の構築","summary":"自動運転モデルが予測した軌跡を走行映像に重ねる動画生成プロセスを、AWS Step FunctionsとBatchを活用して自動化・高速化した事例。従来は手作業でGPU環境を準備し、長時間かけていた処理を、社内ビューアからのリクエストでSlackに動画が届く仕組みへと刷新した。\n\nボトルネックとなっていた学習用データセットの作成工程を最適化し、並列処理を導入することで生成時間を大幅に短縮。さらに、コーディングエージェントを活用してコンテナ内の処理を最適化するプロセスも紹介しており、MLOpsにおける開発効率化の具体的な実践例となっている。","importance":8},{"title":"個人の目標設定に悩んでいたら、アジャイルが言葉を定義し直すきっかけをくれた話","url":"https://zenn.dev/yoshipon_tech/articles/a0e13c3dbd2f7d","source":"Zenn","published_at":"2026-11-26 14:35","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"アジャイルの思考法を用いた個人の目標設定と価値定義の再構築","summary":"個人の目標設定が続かないという悩みを、アジャイル開発の考え方を応用して解決する試み。目標設定における「手段の目的化」という課題に対し、スクラムガイドの「なぜ（Why）」を重視する姿勢を取り入れ、抽象的な「価値」という言葉を自分なりに定義し直すことで、モチベーションを維持する仕組みを構築した。\n\n成果物（アウトプット）ではなく、どのような効果（アウトカム）をもたらしたいかという視点に切り替えることで、目標設定を「やらないといけないこと」から「価値を生み出すための手段」へと昇華させるプロセスを解説。アジャイルの原則を個人の自己研鑽に適用するための実践的なアプローチとなっている。","importance":5}]};
